#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int type;
    int price;
} Item;

int cmpItem(const void *a, const void *b) {
    const Item *x = (const Item *)a;
    const Item *y = (const Item *)b;
    if (x->type != y->type) return x->type - y->type;
    return x->price - y->price;
}

static int *heapPrice;
static int *heapType;
static int heapSize;

void heapPush(int price, int type) {
    int i = ++heapSize;
    while (i > 1) {
        int p = i >> 1;
        if (price < heapPrice[p] || (price == heapPrice[p] && type < heapType[p])) {
            heapPrice[i] = heapPrice[p];
            heapType[i] = heapType[p];
            i = p;
        } else {
            break;
        }
    }
    heapPrice[i] = price;
    heapType[i] = type;
}

void heapPop(void) {
    int lastPrice = heapPrice[heapSize];
    int lastType = heapType[heapSize];
    --heapSize;

    int i = 1;
    while (1) {
        int left = i << 1;
        int right = left | 1;
        int smallest = i;

        if (left <= heapSize &&
            (heapPrice[left] < heapPrice[smallest] ||
             (heapPrice[left] == heapPrice[smallest] && heapType[left] < heapType[smallest]))) {
            smallest = left;
        }
        if (right <= heapSize &&
            (heapPrice[right] < heapPrice[smallest] ||
             (heapPrice[right] == heapPrice[smallest] && heapType[right] < heapType[smallest]))) {
            smallest = right;
        }

        if (smallest == i) break;

        heapPrice[i] = heapPrice[smallest];
        heapType[i] = heapType[smallest];
        i = smallest;
    }

    heapPrice[i] = lastPrice;
    heapType[i] = lastType;
}

int main(void) {
    int N, T;
    if (scanf("%d %d", &N, &T) != 2) return 0;

    Item *items = (Item *)malloc((size_t)N * sizeof(Item));

    for (int i = 0; i < N; ++i) {
        scanf("%d", &items[i].type);
    }
    for (int i = 0; i < N; ++i) {
        scanf("%d", &items[i].price);
    }

    qsort(items, (size_t)N, sizeof(Item), cmpItem);

    int *end = (int *)calloc((size_t)T + 2, sizeof(int));
    int *ptr = (int *)calloc((size_t)T + 2, sizeof(int));

    int heapCap = N + T + 5;
    heapPrice = (int *)malloc((size_t)heapCap * sizeof(int));
    heapType = (int *)malloc((size_t)heapCap * sizeof(int));
    heapSize = 0;

    int i = 0;
    while (i < N) {
        int type = items[i].type;
        int s = i;
        while (i < N && items[i].type == type) {
            ++i;
        }
        ptr[type] = s;
        end[type] = i;
        heapPush(items[s].price, type);
    }

    int C;
    scanf("%d", &C);

    long long ans = 0;

    for (int j = 0; j < C; ++j) {
        int u;
        scanf("%d", &u);

        if (u == 0) {
            while (heapSize > 0) {
                int type = heapType[1];
                int price = heapPrice[1];
                if (ptr[type] < end[type] && items[ptr[type]].price == price) {
                    break;
                }
                heapPop();
            }

            if (heapSize > 0) {
                int type = heapType[1];
                int price = heapPrice[1];
                heapPop();

                ans += price;
                ++ptr[type];

                if (ptr[type] < end[type]) {
                    heapPush(items[ptr[type]].price, type);
                }
            }
        } else {
            int type = u;
            if (ptr[type] < end[type]) {
                int price = items[ptr[type]].price;
                ans += price;
                ++ptr[type];

                if (ptr[type] < end[type]) {
                    heapPush(items[ptr[type]].price, type);
                }
            }
        }
    }

    printf("%lld\n", ans);

    free(items);
    free(end);
    free(ptr);
    free(heapPrice);
    free(heapType);

    return 0;
}
